    void add(SessionChunkEntry entry, int end) {
      _offsetById[entry.record.id] = entry.offset;
      if (prepend) {
        _entries.insert(0, entry.record);
        _offsets.insert(0, entry.offset);
        _ends.insert(0, end);
      } else {
