  /// to complete. See [growOlderUntil] for why the boundary stop waits
  /// for this.
  bool _keptPathResident(List<SessionRecord> branch) {
    CompactionRecord? compaction;
    for (final record in branch) {
      if (record is CompactionRecord) compaction = record;
    }
    if (compaction == null) return true;
    final keptId = compaction.firstKeptEntryId;
    if (keptId.isEmpty) return true; // defensive: nothing to wait for
    return branch.any((record) => record.id == keptId);
  }

  /// Largest single block of the [growOlderUntil] walk — the per-page
  /// doubling ceiling (64 MB / 4096 records keeps one page at ~300 ms and
  /// bounds the transient strip buffer).
  static const maxWalkBlockRecords = 4096;
  static const maxWalkBlockBytes = 64 << 20;

  /// Brings the whole file into residency with a sequential forward scan
  /// (gh-1555 W1 — the read-everything trajectory surfaces): strips read
  /// upward from the file head in bounded chunks, every byte read and
  /// parsed exactly once, spliced into the window in ONE prepend.
  /// [growOlderUntil] cannot do this cheaply: its doubling strips answer
  /// "where is the NEARBY boundary", and its per-strip record cap
  /// truncates each strip — a whole-ledger walk under that cap measured
