  /// (CC ≤ 12) — the loop is one cohesive pass.
  Future<({List<SessionRecord> records, List<int> starts, List<int> ends})>
  _scanFileHeadStrips(int top, int maxBytes) async {
    final records = <SessionRecord>[];
    final starts = <int>[];
    final ends = <int>[];
