  Future<List<TrajectoryHiddenRecordPreview>?> _resolveHiddenPreviews(
    TrajectoryCompactedRecord record,
  ) async {
    final session = _session;
    if (session == null) return null;
    try {
      return await _resolveHiddenPreviewsIn(session, record);
    } on Object {
      return const [];
    }
