final class TrajectoryTailer {
  /// Creates a tailer rendering rows at [width] columns.
  TrajectoryTailer({this.width = 80});

  /// Row width in columns.
  final int width;

  final TrajectorySnapshotBuilder _builder = TrajectorySnapshotBuilder();
  int _seen = 0;

