        await _trajectoryView();
      case 'cost':
        await _trajectoryCost();
      case 'tail':
        await _trajectoryTail();
      case 'inspect':
        await _trajectoryInspect(parts.length > 1 ? parts[1] : '');
      default:
        io.writeln('usage: /trajectory [view|cost|tail|inspect <n>]');
