/// The block-prepend splice shared by [_indexChunk]'s `prepend` branch
/// and [_spliceOlderAbove]: three parallel `insertAll(0, …)` calls (one
/// memmove per list instead of O(window) per record) plus the per-record
/// re-index. Keeping ONE copy guards the window-list invariant (the
/// three parallel lists stay in the same file order) against drift.
void _blockPrepend(List<SessionRecord> records, List<int> starts, List<int> ends) {
  _entries.insertAll(0, records);
  _offsets.insertAll(0, starts);
  _ends.insertAll(0, ends);
  for (var i = 0; i < records.length; i++) {
    final record = records[i];
    _byId[record.id] = record;
    _offsetById[record.id] = starts[i];
    _appendedBelow.remove(record.id);
    updateSessionLabelCache(_labelsById, record);
  }
```

