      final entries = await windowed.getEntries();
      expect(idsOf(entries).last, 'e10');
      expect(await windowed.getLeafId(), 'e10');
      // Idempotent when nothing new landed.
      expect((await windowed.ingestAppended()).delta, isEmpty);
    });

