          '"tokensBefore":12345}\n',
        );
      }
      buffer.write(
        '{"type":"message","id":"e$i","parentId":'
        '${i == 0 && compactionAt != 0 ? 'null' : (compactionAt == i ? '"c$i"' : '"e${i - 1}"')},'
        '"timestamp":"$iso",'
        '"message":{"role":"user","content":[{"type":"text","text":'
