/// read is chunked, never one materialized whole-file string. A no-op
/// for full storages.
Future<void> ensureWholeLedgerResident() async {
  final storage = _storage;
  if (storage is! WindowedSessionStorage) return;
  await storage.loadAllOlder();
}

